<?php $image = (string) ($product['image_url'] ?? ''); $price = (float) $product['price'] * (1 - (float) $product['discount_percent'] / 100); ?>
<section class="section-wrap product-detail"><div class="detail-visual"><?php if ($image !== ''): ?><img src="<?= $e($image) ?>" alt="<?= $e($product['name']) ?>"><?php else: ?><div class="detail-orb"><span>✳</span><small>SHIFA · EVERYDAY CARE</small></div><?php endif; ?></div><div class="detail-copy"><p class="eyebrow">A LITTLE CARE, EVERY DAY</p><h1><?= $e($product['name']) ?></h1><div class="detail-price"><?= number_format($price, 2) ?> JOD <?php if ((float) $product['discount_percent'] > 0): ?><del><?= number_format((float) $product['price'], 2) ?> JOD</del><?php endif; ?></div><p class="detail-description"><?= nl2br($e($product['description'] ?? 'A considered essential for your everyday routine.')) ?></p><div class="stock-note"><span></span><?= (int) $product['stock'] > 0 ? 'In stock · Ships with care' : 'Currently unavailable' ?></div><?php if ((int) $product['stock'] > 0): ?><form class="detail-form" action="<?= $e($base) ?>/cart/add" method="post"><input type="hidden" name="csrf_token" value="<?= $e($csrf_token) ?>"><input type="hidden" name="product_id" value="<?= (int) $product['id'] ?>"><label>Quantity<input type="number" name="quantity" value="1" min="1" max="<?= (int) $product['stock'] ?>"></label><?php if ($product['sizes']): ?><label>Size<select name="size"><?php foreach ($product['sizes'] as $size): ?><option value="<?= $e($size) ?>"><?= $e($size) ?></option><?php endforeach; ?></select></label><?php else: ?><input type="hidden" name="size" value=""><?php endif; ?><button class="button button-dark" type="submit">Add to your bag <span>↗</span></button></form><?php endif; ?><div class="detail-meta"><p>✳&nbsp; Thoughtfully selected for everyday wellbeing</p><p>♡&nbsp; Questions? We’re here to help</p></div><?php if (!empty($product['ingredients'])): ?><details class="detail-accordion"><summary>Ingredients</summary><p><?= nl2br($e($product['ingredients'])) ?></p></details><?php endif; ?><?php if (!empty($product['warnings'])): ?><details class="detail-accordion"><summary>Good to know</summary><p><?= nl2br($e($product['warnings'])) ?></p></details><?php endif; ?></div></section>
